content:
{
  "model": "veo-3.1-generate-preview",
  "defaults": {
    "aspectRatio": "16:9",
    "durationSeconds": 8,
    "resolution": "1080p",
    "personGeneration": "allow_all"
  },
  "continuityLock": "Same Chilean neighborhood retail business, same owner in early 30s with consistent neutral contemporary wardrobe and appearance, same recurring customer, pale oak, warm white plaster, soft concrete, large front window, natural daylight, bright airy premium editorial documentary photography, restrained contrast, subtle film grain, no baked-in text, logos, UI or watermarks, no cyberpunk, neon, holograms, floating dashboards or CGI/3D-render appearance.",
  "scenes": [
    {
      "id": "hero",
      "number": "01",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Photorealistic editorial film of the same real Chilean neighborhood retail shop opening in the morning. Pale oak counter, warm white plaster, soft concrete floor, front window with gentle daylight, believable everyday products, lived-in details, no posing. Very slow forward dolly toward the entrance as morning light fills the space. Calm premium human documentary realism. End on a composition that can hand off naturally to the owner at the counter."
    },
    {
      "id": "sales",
      "number": "02",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "The same owner and shop, same wardrobe and natural light, serving a customer during a normal retail sale. Emphasize hands, product handoff and payment rather than faces. Slow lateral camera drift toward the hands and payment moment. The final composition should leave a natural path toward recognizing the returning customer. No readable text or logos."
    },
    {
      "id": "customers",
      "number": "03",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "The same customer returns to the same store. The owner recognizes them naturally; warm human interaction without posing. Begin from the previous product/payment action, then use shallow depth of field and a gentle rack focus from product to customer to owner, followed by a subtle push-in. Same wardrobe, materials and daylight."
    },
    {
      "id": "inventory",
      "number": "04",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Move continuously from the same front counter into the shop storage area. Real shelves with believable imperfect stock, boxes and products with labels that are not readable. The owner searches for one product. Controlled documentary camera movement deeper into storage, side light from the shop, realistic materials, no warehouse exaggeration."
    },
    {
      "id": "scanner",
      "number": "05",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Macro cinematic close-up continuing from the storage product search: the same owner's hand holds a real retail product and brings a barcode scanner or phone close to the barcode. Focus on physical action, product texture and realistic hand movement. Slow macro push toward the barcode, subtle scan gesture, then rack focus back to the product. No generated UI or readable text."
    },
    {
      "id": "purchases",
      "number": "06",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Continue from the scanned product into the same storage area. A shelf has a visible gap where a product is running low. The owner notices the gap and checks context on a phone or laptop nearby. Start on the empty shelf space and gently reframe toward the owner's decision. Physical reality remains primary; no floating interface."
    },
    {
      "id": "cash",
      "number": "07",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Return naturally to the same front counter. A customer completes a payment using a realistic contactless terminal; receipt and product handoff follow. Bright natural light, believable retail environment. Short controlled push toward the payment moment and settle. The final frame should make a package or product handoff easy to continue into dispatch."
    },
    {
      "id": "shipping",
      "number": "08",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "The same owner places a carefully packed plain package on the counter and hands it toward a courier or the shop door. Continue the previous handoff motion. Controlled tracking movement follows the package from counter toward the exit. Same materials, daylight and documentary realism. No logos or text on the package."
    },
    {
      "id": "finance",
      "number": "09",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "After the dispatch movement, return to the same owner later in the same shop, calmer, reviewing the day's business on a laptop at the same counter. Golden natural light, quieter reflective but optimistic mood. Laptop display remains soft and abstract with no readable generated text. Very slow orbit or reframe around the owner revealing the store context."
    },
    {
      "id": "score",
      "number": "10",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Continue the financial review into a calmer, wider view of the same business. The shop now feels subtly more ordered and intentional than at the opening. The owner remains part of the real environment. Slow controlled pull-back revealing the full business context. Leave clean visual space for a Nüva Score data insert added by the website. No floating graphics in the generated video."
    },
    {
      "id": "automation",
      "number": "11",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "The same owner continues a normal shop task while a small operational event resolves in the background: a discreet notification appears on a physical phone or laptop, the owner notices it briefly and continues working. The business keeps moving instead of stopping for administration. Subtle time compression in background activity, controlled camera, no holograms or floating dashboards."
    },
    {
      "id": "studio",
      "number": "12",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Over-the-shoulder view of the same owner asking a question on a laptop in the same shop. Continue naturally from the previous device notification. Screen is intentionally soft and abstract with no readable generated text; the website supplies the actual interface. The owner looks focused, then relaxed. Slow over-shoulder push toward the laptop with shallow depth of field."
    },
    {
      "id": "connections",
      "number": "13",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Pull back from the laptop into a wide editorial composition of the same business environment: owner, phone, laptop, payment terminal and packaged order are ordinary physical objects within one coherent workspace. Nothing floats. The sense of connection comes from composition and continuity. Controlled pull-back reveals the whole operational ecosystem in one frame."
    },
    {
      "id": "final",
      "number": "14",
      "firstFrame": null,
      "lastFrame": null,
      "prompt": "Return to the exact visual world of scene 01: same shop, same camera family, same owner and location cues. The space now feels subtly more ordered and calm. Soft daylight and generous negative space for the final Nüva One CTA. Slow pull-back and hold on a clean stable final frame. It must feel like returning to the beginning after the business has changed."
    }
  ]
}
